import { useCallback, useState } from 'react';
import { Button, Drawer } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

type NavItem = {
  key: NavKey;
  label: string;
  danger?: boolean;
};

const ITEMS: NavItem[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

const LOGOUT: NavItem = { key: 'logout', label: 'Выйти', danger: true };

export type SideNavProps = {
  onNavigate: (key: NavKey) => void;
};

export default function SideNav({ onNavigate }: SideNavProps) {
  const [open, setOpen] = useState(false);

  const close = useCallback(() => setOpen(false), []);

  const select = useCallback(
    (key: NavKey) => {
      onNavigate(key);
      setOpen(false);
    },
    [onNavigate],
  );

  const renderItem = (item: NavItem) => (
    <Button
      key={item.key}
      variant="ghost"
      tone={item.danger ? 'danger' : 'neutral'}
      role="menuitem"
      onClick={() => select(item.key)}
      style={{ width: '100%', justifyContent: 'flex-start' }}
    >
      {item.label}
    </Button>
  );

  return (
    <>
      <Button
        variant="solid"
        aria-haspopup="menu"
        aria-expanded={open}
        onClick={() => setOpen(true)}
      >
        Меню
      </Button>

      <Drawer
        open={open}
        onClose={close}
        side="left"
        aria-label="Основная навигация"
      >
        <nav
          role="menu"
          aria-label="Основная навигация"
          className="jx-stack"
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--jx-space-1)',
            padding: 'var(--jx-space-3)',
            minWidth: 'var(--jx-size-drawer, 240px)',
          }}
        >
          {ITEMS.map(renderItem)}

          <div
            role="separator"
            style={{
              height: 'var(--jx-border-width)',
              margin: 'var(--jx-space-2) 0',
              background: 'var(--jx-color-border)',
            }}
          />

          {renderItem(LOGOUT)}
        </nav>
      </Drawer>
    </>
  );
}

